import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 3.2;
  const height = (320 / 512) * width;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const tex = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  tex.colorSpace = THREE.SRGBColorSpace;

  const inkColor = new THREE.Color('#16161d');
  const surfaceColor = new THREE.Color('#0b0b10');

  const grainStrength = uniform(0.035);

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = false;

  const baseTex = texture(tex, uv());

  const gradientMix = uv().y;
  const gradientColor = mix(vec4(surfaceColor, 1.0), vec4(inkColor, 1.0), gradientMix);

  const grainNoise = uv().x.mul(1234.5).sin().mul(uv().y.mul(789.3).cos()).fract().sub(0.5).mul(grainStrength);

  material.colorNode = baseTex.mul(0.82).add(gradientColor.mul(0.18)).add(vec4(grainNoise, grainNoise, grainNoise, 0.0));

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'collection-title-plane';
  group.add(plane);

  const textMeshes = [];

  const textContent = Array.isArray(config.textContent) ? config.textContent : [];
  textContent.forEach((entry, index) => {
    const textMesh = ctx.fontAtlas.createText({
      text: entry.text,
      font: entry.role === 'body' || entry.role === 'caption' ? 'JetBrains Mono' : 'Lora',
      weight: entry.weight || 400,
      role: entry.role,
      sizeEm: entry.role === 'headline' ? 0.34 : 0.2,
      color: '#e8ecf2',
      atlasRegion: config.atlasRegion,
    });
    textMesh.name = `collection-title-text-${index}`;
    textMesh.position.set(0, 0, 0.02);
    group.add(textMesh);
    textMeshes.push(textMesh);
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
    textMeshes.forEach((textMesh) => {
      if (textMesh.userData && typeof textMesh.userData.cleanup === 'function') {
        textMesh.userData.cleanup();
      } else {
        if (textMesh.geometry) textMesh.geometry.dispose();
        if (textMesh.material) textMesh.material.dispose();
      }
    });
  };

  return group;
}
